import java.util.*;

class Solution {
  public boolean isRectangleCover(int[][] rectangles) {
    long area = 0;
    int minX = Integer.MAX_VALUE,
        minY = Integer.MAX_VALUE,
        maxX = Integer.MIN_VALUE,
        maxY = Integer.MIN_VALUE;
    Set<String> corners = new HashSet<>();
    for (int[] r : rectangles) {
      minX = Math.min(minX, r[0]);
      minY = Math.min(minY, r[1]);
      maxX = Math.max(maxX, r[2]);
      maxY = Math.max(maxY, r[3]);
      area += (long) (r[2] - r[0]) * (r[3] - r[1]);
      toggle(corners, r[0], r[1]);
      toggle(corners, r[0], r[3]);
      toggle(corners, r[2], r[1]);
      toggle(corners, r[2], r[3]);
    }
    if (area != (long) (maxX - minX) * (maxY - minY) || corners.size() != 4) return false;
    return corners.contains(key(minX, minY))
        && corners.contains(key(minX, maxY))
        && corners.contains(key(maxX, minY))
        && corners.contains(key(maxX, maxY));
  }

  private void toggle(Set<String> set, int x, int y) {
    String k = key(x, y);
    if (!set.add(k)) set.remove(k);
  }

  private String key(int x, int y) {
    return x + ":" + y;
  }
}
